"""Exception definitions."""

from jsilib import _utils, exc

from .interface import IJSIAcceptor

__all__ = export = _utils.ExportList()


@export
class JSIError(exc.JSILIBError):
    """Base class for JSI protocol errors."""


@export
class ProtocolError(JSIError):
    """Raised when incoming or outgoing frame is not allowed in current
    state."""
    __message_template__ = "{self.message}"

    def __init__(self, message: str):
        super().__init__()
        self._message = message

    @property
    def message(self) -> str:
        return self._message


@export
class TransferRejectedError(JSIError):
    """Raised when data transfer was rejected by peer.

    This can happend when outgoing JSI message transfer is terminated by remote
    peer before completion.
    """


@export
class ConnectionClosedError(JSIError):
    """Raised when message is being read from or written to a closed
    connection.

    This exception will directly be raised if connection is explicitly closed
    by user. If connection is closed by peer or transport error, one of its
    subclasses will be raised instead.
    """


@export
class ConnectionClosedByTransport(ConnectionClosedError):
    """Raised when connection was closed due to error in transport layer.

    This may happen if transport connection is explicitly closed.
    """


@export
class ConnectionClosedByPeer(ConnectionClosedError):
    """Raised when connection was closed gracefully by peer.

    This will happen if a TERM frame is received.
    """


@export
class ConnectionClosedByPingLoss(ConnectionClosedError):
    """Raised when connection was closed due to too many lost keep alive pings
    in a row."""


@export
class AcceptorClosedError(JSIError):
    """Raised when :meth:`IAcceptor.accept` is called on an acceptor that is
    already closed."""

    def __init__(self, acceptor: IJSIAcceptor):
        super().__init__()
        self._acceptor = acceptor

    @property
    def acceptor(self) -> IJSIAcceptor:
        """The acceptor that was closed."""
        return self._acceptor


@export
class MessageCacheClosedError(JSIError):
    """Raised when user is trying to access a cached message that was
    closed."""
